from taf.selenium.mobile.core.common.common import CustomPagePart
from taf.selenium.mobile.gnb.oam.coam.classical.pages.login_management import (CoamLoginManagementPage,
                                                                               LabAccessLoginManagementPage)
from taf.selenium.mobile.gnb.oam.coam.classical.pages.bts_status import SiteViewPage
from taf.selenium.mobile.gnb.oam.coam.classical.pages.software import SoftwareManagementPage
from taf.selenium.mobile.gnb.oam.coam.classical.pages.factory import LoginManagement, BtsStatus, Software
from taf.selenium.mobile.gnb.oam.coam.classical.pages.menu_list import MenuList
from taf.selenium.mobile.gnb.oam.coam.classical.pages.modals import BtsStartUpViewModal


class Coam(object):
    """Based on coam 20B version."""

    def __init__(self, driver, download_checker, screenshot_dir):
        self._driver = driver
        self._download_checker = download_checker
        self._screenshot_dir = screenshot_dir
        self._tool = CustomPagePart(driver, download_checker, screenshot_dir)

        self._login_management = LoginManagement(self._init_login_management_page_list())
        self._bts_status = BtsStatus(self._init_bts_status_page_list())
        self._software = Software(self._init_software_page_list())
        self._menu_list = MenuList(self._tool)
        self._bts_start_up_view_modal = BtsStartUpViewModal(self._tool)

    @property
    def menu_list(self):
        return self._menu_list

    @property
    def download_checker(self):
        return self._download_checker

    @property
    def debug(self):
        return self._tool

    @property
    def browser(self):
        return self._tool

    @property
    def login_management(self):
        return self._login_management

    @property
    def bts_status(self):
        return self._bts_status

    @property
    def software(self):
        return self._software

    @property
    def bts_start_up_view_modal(self):
        return self._bts_start_up_view_modal

    def _init_login_management_page_list(self):
        coam_login_management_page = CoamLoginManagementPage(self._tool)
        lab_access_login_management_page = LabAccessLoginManagementPage(self._tool)
        return {'coam_login_management': coam_login_management_page,
                'lab_access_login_management': lab_access_login_management_page}

    def _init_bts_status_page_list(self):
        site_view_page = SiteViewPage(self._tool)
        return {'site_view': site_view_page}

    def _init_software_page_list(self):
        software_management_page = SoftwareManagementPage(self._tool)
        return {'software_management': software_management_page}


class Coam21A(Coam):
    def __init__(self, driver, download_checker, screenshot_dir):
        super(Coam21A, self).__init__(driver, download_checker, screenshot_dir)
